def merge_intervals(intervals):
    """Combine overlapping half-open intervals in ascending order."""
    ordered = sorted(intervals)
    merged = []
    for start, end in ordered:
        if start > end:
            raise ValueError('reversed interval')
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return [tuple(item) for item in merged]

def roman_to_int(text):
    """Parse a canonical uppercase Roman numeral."""
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    previous = 0
    for symbol in reversed(text):
        value = values[symbol]
        total += -value if value < previous else value
        previous = max(previous, value)
    return total

def topological_order(graph):
    """Return a dependency order or raise when a directed cycle exists."""
    incoming = {node: 0 for node in graph}
    for edges in graph.values():
        for node in edges:
            incoming[node] = incoming.get(node, 0) + 1
    ready = sorted(node for node, degree in incoming.items() if degree == 0)
    result = []
    while ready:
        node = ready.pop(0)
        result.append(node)
        for child in graph.get(node, []):
            incoming[child] -= 1
            if incoming[child] == 0:
                ready.append(child); ready.sort()
    if len(result) != len(incoming):
        raise ValueError('cycle')
    return result

from collections import deque

class RollingAverage:
    """Maintain a fixed-width mean without rescanning prior values."""
    def __init__(self, width):
        if width < 1:
            raise ValueError('positive width required')
        self.width = width
        self.values = deque()
        self.total = 0.0
    def add(self, value):
        self.values.append(float(value)); self.total += value
        if len(self.values) > self.width:
            self.total -= self.values.popleft()
        return self.total / len(self.values)

def balanced_brackets(source):
    """Check three bracket types while ignoring other characters."""
    closing = {')': '(', ']': '[', '}': '{'}
    stack = []
    for character in source:
        if character in closing.values():
            stack.append(character)
        elif character in closing:
            if not stack or stack.pop() != closing[character]:
                return False
    return not stack

def run_length_encode(values):
    """Encode adjacent equal values as value-count pairs."""
    iterator = iter(values)
    try:
        current = next(iterator)
    except StopIteration:
        return []
    output, count = [], 1
    for value in iterator:
        if value == current:
            count += 1
        else:
            output.append((current, count)); current, count = value, 1
    output.append((current, count))
    return output

def lower_bound(items, target):
    """Find the first position whose sorted value is at least target."""
    low, high = 0, len(items)
    while low < high:
        middle = low + (high - low) // 2
        if items[middle] < target:
            low = middle + 1
        else:
            high = middle
    return low

def csv_field(value):
    """Render one RFC-style CSV field with minimal quoting."""
    text = str(value)
    if any(mark in text for mark in (',', '"', '\n', '\r')):
        return '"' + text.replace('"', '""') + '"'
    return text

def csv_row(values):
    return ','.join(csv_field(value) for value in values) + '\n'

from collections import OrderedDict

class LRUCache:
    """Evict the least recently accessed entry at fixed capacity."""
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()
    def get(self, key):
        value = self.data.pop(key)
        self.data[key] = value
        return value
    def put(self, key, value):
        self.data.pop(key, None); self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

def transpose(matrix):
    """Transpose a rectangular matrix and reject ragged input."""
    if not matrix:
        return []
    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError('ragged matrix')
    return [[matrix[row][column] for row in range(len(matrix))]
            for column in range(width)]

import heapq

class RunningMedian:
    def __init__(self):
        self.lower, self.upper = [], []
    def add(self, value):
        heapq.heappush(self.lower, -value)
        heapq.heappush(self.upper, -heapq.heappop(self.lower))
        if len(self.upper) > len(self.lower):
            heapq.heappush(self.lower, -heapq.heappop(self.upper))
    def value(self):
        if not self.lower:
            raise ValueError('empty')
        if len(self.lower) == len(self.upper):
            return (-self.lower[0] + self.upper[0]) / 2
        return -self.lower[0]

def deep_get(document, path, default=None):
    """Follow mapping keys and sequence indexes without masking type errors."""
    current = document
    for component in path:
        try:
            current = current[component]
        except (KeyError, IndexError):
            return default
    return current

def missing_ranges(observed, lower, upper):
    """Return inclusive gaps inside a bounded integer domain."""
    cursor, gaps = lower, []
    for value in sorted(set(observed)):
        if value < lower or value > upper:
            continue
        if cursor < value:
            gaps.append((cursor, value - 1))
        cursor = value + 1
    if cursor <= upper:
        gaps.append((cursor, upper))
    return gaps

import re
from collections import Counter

def word_frequency(text):
    """Count case-folded words while preserving apostrophes inside words."""
    tokens = re.findall(r"[^\W_]+(?:'[^\W_]+)?", text.casefold(), flags=re.UNICODE)
    return Counter(tokens)

def most_common_words(text, limit):
    return word_frequency(text).most_common(limit)

import heapq

def shortest_paths(graph, start):
    """Compute nonnegative weighted distances from one node."""
    distance = {start: 0}
    queue = [(0, start)]
    while queue:
        cost, node = heapq.heappop(queue)
        if cost != distance[node]:
            continue
        for neighbor, weight in graph.get(node, []):
            if weight < 0:
                raise ValueError('negative edge')
            candidate = cost + weight
            if candidate < distance.get(neighbor, float('inf')):
                distance[neighbor] = candidate
                heapq.heappush(queue, (candidate, neighbor))
    return distance

def retry_delays(initial, factor, attempts, ceiling):
    """Produce bounded exponential delays for retry attempts."""
    if initial < 0 or factor < 1 or attempts < 0:
        raise ValueError('invalid retry policy')
    delay = initial
    result = []
    for _ in range(attempts):
        result.append(min(delay, ceiling))
        delay = min(delay * factor, ceiling)
    return result

def changed_lines(before, after):
    """Yield line numbers whose values differ, including appended lines."""
    left, right = before.splitlines(), after.splitlines()
    count = max(len(left), len(right))
    for index in range(count):
        old = left[index] if index < len(left) else None
        new = right[index] if index < len(right) else None
        if old != new:
            yield index + 1, old, new

from collections import deque

def breadth_levels(graph, start):
    """Map each reachable node to its unweighted distance."""
    distance = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)
    return distance

def reservoir_sample(stream, count, random_source):
    """Select a uniform fixed-size sample from a stream of unknown length."""
    sample = []
    for index, value in enumerate(stream):
        if index < count:
            sample.append(value)
            continue
        chosen = random_source.randrange(index + 1)
        if chosen < count:
            sample[chosen] = value
    return sample

import re

def parse_duration(value):
    """Parse compact hour, minute, and second components into seconds."""
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', value)
    if not match or not any(match.groups()):
        raise ValueError('invalid duration')
    hours, minutes, seconds = (int(part or 0) for part in match.groups())
    if minutes >= 60 or seconds >= 60:
        raise ValueError('component out of range')
    return hours * 3600 + minutes * 60 + seconds

def flatten_tree(node):
    """Walk a nested name-children mapping in preorder."""
    if set(node) != {'name', 'children'}:
        raise ValueError('malformed node')
    yield node['name']
    for child in node['children']:
        yield from flatten_tree(child)

def tree_names(root):
    return list(flatten_tree(root))

def internet_checksum(data):
    """Compute the sixteen-bit one's-complement checksum of bytes."""
    if len(data) % 2:
        data += b'\x00'
    total = 0
    for offset in range(0, len(data), 2):
        total += int.from_bytes(data[offset:offset + 2], 'big')
        total = (total & 0xffff) + (total >> 16)
    return (~total) & 0xffff

from urllib.parse import unquote_plus

def parse_query(query):
    """Parse a URL query into an ordered list of decoded name-value pairs."""
    if query.startswith('?'):
        query = query[1:]
    result = []
    for field in filter(None, query.split('&')):
        name, separator, value = field.partition('=')
        result.append((unquote_plus(name), unquote_plus(value) if separator else ''))
    return result

def stable_partition(values, predicate):
    """Keep relative order while moving matching values before the rest."""
    accepted, rejected = [], []
    for value in values:
        (accepted if predicate(value) else rejected).append(value)
    return accepted + rejected

def histogram(values, edges):
    """Count values in left-closed bins with the final edge inclusive."""
    if sorted(edges) != list(edges) or len(set(edges)) != len(edges):
        raise ValueError('edges must increase')
    counts = [0] * (len(edges) - 1)
    for value in values:
        for index, (left, right) in enumerate(zip(edges, edges[1:])):
            if left <= value < right or (index == len(counts) - 1 and value == right):
                counts[index] += 1; break
    return counts

def edit_distance(left, right):
    """Compute Levenshtein distance with one dynamic-programming row."""
    previous = list(range(len(right) + 1))
    for row, a in enumerate(left, 1):
        current = [row]
        for column, b in enumerate(right, 1):
            current.append(min(current[-1] + 1, previous[column] + 1,
                               previous[column - 1] + (a != b)))
        previous = current
    return previous[-1]

class TokenBucket:
    """Track a deterministic token bucket using caller-supplied time."""
    def __init__(self, capacity, rate, now):
        self.capacity = capacity; self.rate = rate
        self.tokens = float(capacity); self.updated = now
    def take(self, amount, now):
        elapsed = max(0, now - self.updated)
        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
        self.updated = now
        if amount > self.tokens:
            return False
        self.tokens -= amount
        return True
